/**
 * Keep Escape consistent with the design contract when Core Navigation uses
 * its combined hover-and-click submenu mode.
 *
 * Core closes the click/focus state on Escape, but its hover state can remain
 * active while the pointer is still over the parent item. A synthetic
 * pointerleave clears that second state without changing the parent link /
 * submenu-toggle markup generated by WordPress.
 */
( function () {
	'use strict';
	var submenuSelector = '.lpu-header .wp-block-navigation-submenu';

	function syncHeaderVariant() {
		var header = document.querySelector( '.lpu-header' );

		if ( ! header ) {
			return;
		}

		var menuOpen = Boolean(
			header.querySelector(
				'.wp-block-navigation__responsive-container.is-menu-open,' +
				' .wp-block-navigation__submenu-icon[aria-expanded="true"]'
			)
		);
		var transparentPage = document.body.classList.contains(
			'lpu-header-transparent'
		);
		var logo = header.querySelector( 'img[data-lpu-transparent-src]' );

		header.classList.toggle( 'lpu-menu-open', menuOpen );

		if ( ! logo ) {
			return;
		}

		var sourceAttribute = transparentPage && ! menuOpen
			? 'data-lpu-transparent-src'
			: 'data-lpu-opaque-src';
		var source = logo.getAttribute( sourceAttribute );

		if ( source && logo.getAttribute( 'src' ) !== source ) {
			logo.setAttribute( 'src', source );
		}
	}

	function scheduleHeaderVariantSync() {
		window.setTimeout( syncHeaderVariant, 0 );
	}

	new MutationObserver( scheduleHeaderVariantSync ).observe(
		document.documentElement,
		{
			attributes: true,
			attributeFilter: [ 'aria-expanded', 'class' ],
			subtree: true,
		}
	);
	document.addEventListener( 'click', scheduleHeaderVariantSync );
	document.addEventListener( 'keydown', scheduleHeaderVariantSync );
	syncHeaderVariant();

	function getSubmenu( target ) {
		return target instanceof Element ? target.closest( submenuSelector ) : null;
	}

	var topLevelSubmenuSelector =
		'.lpu-header .wp-block-navigation__container > .wp-block-navigation-submenu';
	var hoverBridgeClass = 'lpu-hover-bridge-open';
	var hoverPendingClass = 'lpu-hover-pending';
	var hoverBridgeDelay = 500;
	var hoverSwitchDelay = 150;
	var hoverBridgeSubmenu = null;
	var hoverBridgeTimer = null;
	var hoverPendingSubmenu = null;
	var hoverPendingTimer = null;

	function getTopLevelSubmenu( target ) {
		return target instanceof Element
			? target.closest( topLevelSubmenuSelector )
			: null;
	}

	function isDesktopNavigation() {
		return window.matchMedia( '(min-width: 1100px)' ).matches;
	}

	function cancelHoverBridgeTimer() {
		if ( null !== hoverBridgeTimer ) {
			window.clearTimeout( hoverBridgeTimer );
			hoverBridgeTimer = null;
		}
	}

	function releaseHoverBridge( submenu ) {
		if ( submenu ) {
			submenu.classList.remove( hoverBridgeClass );
		}

		if ( hoverBridgeSubmenu === submenu ) {
			hoverBridgeSubmenu = null;
		}
	}

	function cancelPendingHoverSwitch() {
		if ( null !== hoverPendingTimer ) {
			window.clearTimeout( hoverPendingTimer );
			hoverPendingTimer = null;
		}

		if ( hoverPendingSubmenu ) {
			hoverPendingSubmenu.classList.remove( hoverPendingClass );
			hoverPendingSubmenu = null;
		}
	}

	function activatePendingHoverSubmenu() {
		var submenu = hoverPendingSubmenu;

		cancelPendingHoverSwitch();

		if ( ! submenu || ! submenu.matches( ':hover' ) ) {
			return;
		}

		if ( hoverBridgeSubmenu && hoverBridgeSubmenu !== submenu ) {
			releaseHoverBridge( hoverBridgeSubmenu );
		}

		hoverBridgeSubmenu = submenu;
	}

	function schedulePendingHoverSwitch( submenu ) {
		cancelPendingHoverSwitch();

		submenu.classList.add( hoverPendingClass );
		hoverPendingSubmenu = submenu;
		hoverPendingTimer = window.setTimeout(
			activatePendingHoverSubmenu,
			hoverSwitchDelay
		);
	}

	function enterTopLevelSubmenu( event ) {
		if ( ! isDesktopNavigation() ) {
			return;
		}

		var submenu = getTopLevelSubmenu( event.target );

		if (
			! submenu
			|| (
				event.relatedTarget instanceof Node
				&& submenu.contains( event.relatedTarget )
			)
		) {
			return;
		}

		if ( hoverPendingSubmenu && hoverPendingSubmenu !== submenu ) {
			cancelPendingHoverSwitch();
		}

		if ( hoverPendingSubmenu === submenu ) {
			return;
		}

		// The first parent opens immediately through Core's native :hover state.
		// The short pending state is only needed when another panel is already
		// active and the pointer may be crossing that parent accidentally.
		if ( ! hoverBridgeSubmenu ) {
			cancelPendingHoverSwitch();
			cancelHoverBridgeTimer();
			hoverBridgeSubmenu = submenu;
			submenu.classList.remove( hoverBridgeClass );
			return;
		}

		if ( hoverBridgeSubmenu === submenu ) {
			cancelHoverBridgeTimer();
			submenu.classList.remove( hoverBridgeClass );
			return;
		}

		schedulePendingHoverSwitch( submenu );
	}

	function leaveTopLevelSubmenu( event ) {
		if ( ! isDesktopNavigation() ) {
			return;
		}

		var submenu = getTopLevelSubmenu( event.target );

		if (
			! submenu
			|| submenu.classList.contains( 'lpu-submenu-escape-closed' )
			|| (
				event.relatedTarget instanceof Node
				&& submenu.contains( event.relatedTarget )
			)
		) {
			return;
		}

		if ( hoverPendingSubmenu === submenu ) {
			cancelPendingHoverSwitch();
			return;
		}

		if ( hoverBridgeSubmenu !== submenu ) {
			return;
		}

		cancelHoverBridgeTimer();

		hoverBridgeSubmenu = submenu;
		submenu.classList.add( hoverBridgeClass );
		hoverBridgeTimer = window.setTimeout( function () {
			if ( ! submenu.matches( ':hover' ) ) {
				releaseHoverBridge( submenu );
			} else {
				submenu.classList.remove( hoverBridgeClass );
			}

			hoverBridgeTimer = null;
		}, hoverBridgeDelay );
	}

	// The bridge covers the short diagonal/horizontal traversal between a
	// top-level parent and its full-width panel. It does not replace Core's
	// hover behavior or make another parent sticky: another parent must remain
	// hovered through the short intent delay before the previous bridge yields.
	document.addEventListener( 'pointerenter', enterTopLevelSubmenu, true );
	document.addEventListener( 'pointerleave', leaveTopLevelSubmenu, true );

	function clearEscapeClosedState( event ) {
		var submenu = getSubmenu( event.target );

		if ( submenu ) {
			submenu.classList.remove( 'lpu-submenu-escape-closed' );
		}
	}

	// A new pointer entry or an explicit toggle action starts a fresh cycle.
	document.addEventListener( 'pointerenter', clearEscapeClosedState, true );
	document.addEventListener( 'click', clearEscapeClosedState );

	// Core's full-screen overlay leaves a small outside margin around the
	// dialog. Treat a click on that margin as an outside click and use Core's
	// own close action so focus returns to the hamburger.
	document.addEventListener( 'click', function ( event ) {
		var target = event.target;
		var overlay = target instanceof Element
			? target.closest(
					'.lpu-header .wp-block-navigation__responsive-container.is-menu-open'
			  )
			: null;

		if ( ! overlay || target !== overlay ) {
			return;
		}

		var closeButton = overlay.querySelector(
			'.wp-block-navigation__responsive-container-close'
		);

		if ( closeButton ) {
			closeButton.click();
		}
	} );

	document.addEventListener( 'keydown', function ( event ) {
		var submenu = getSubmenu( event.target );

		if ( submenu && 'Escape' !== event.key ) {
			submenu.classList.remove( 'lpu-submenu-escape-closed' );
		}

		if ( 'Escape' !== event.key ) {
			return;
		}

		cancelPendingHoverSwitch();

		var openSubmenus = document.querySelectorAll( submenuSelector );

		openSubmenus.forEach( function ( submenu ) {
			var toggle = submenu.querySelector(
				':scope > .wp-block-navigation__submenu-icon[aria-expanded="true"]'
			);

			if ( ! toggle ) {
				return;
			}

			submenu.classList.add( 'lpu-submenu-escape-closed' );

			if ( window.PointerEvent ) {
				submenu.dispatchEvent(
					new PointerEvent( 'pointerleave', {
						bubbles: true,
						pointerType: 'mouse',
					} )
				);
			}

			window.setTimeout( function () {
				if ( 'true' !== toggle.getAttribute( 'aria-expanded' ) ) {
					toggle.focus();
				}
			}, 0 );
		} );
	}, true );
} )();
